<template>
  <view class="withdraw-page"><view class="nav"><text class="back" @tap="back">‹</text><text>申请提现</text><view /></view><view class="body"><view class="bank-choice" @tap="chooseCard"><view class="bank-logo">工</view><view><b>{{ selectedCard.bank }}（尾号{{ selectedCard.tail }}）</b><text>预计 2 小时内到账</text></view><view class="chevron" /></view><view class="amount-card"><text>提现金额</text><view class="amount-input"><text>¥</text><input v-model="amount" type="digit" placeholder="0.00" placeholder-class="placeholder" /></view><view class="available"><text>当前可提现佣金 {{ formattedAvailable }} 元</text><text @tap="fillAll">全部提现</text></view></view><button class="confirm" :disabled="!isAmountValid" @tap="openPassword">确认提现</button><text class="rule">单笔提现金额不得超过可提现佣金余额</text></view>
    <view v-if="showPassword" class="mask"><view class="password-panel"><text class="close" @tap="closePassword">×</text><text class="panel-title">确认支付密码</text><text class="amount-title">提现金额</text><text class="panel-amount">¥{{ normalizedAmount }}</text><view class="password-boxes"><view v-for="index in 6" :key="index" class="box"><i v-if="password.length >= index" /></view></view><text class="forgot" @tap="goForgot">忘记支付密码？</text><view class="keypad"><view v-for="key in keys" :key="key" @tap="pressKey(key)">{{ key }}</view><view @tap="pressKey('delete')">⌫</view></view></view></view>
    <view v-if="showError" class="dialog-mask"><view class="error-dialog"><text>支付密码错误，请重新输入</text><view><button @tap="goForgot">忘记密码</button><button class="retry" @tap="retry">重新输入</button></view></view></view>
  </view>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { enforcePortal } from '../../core/route-guard'
import { wallet, withdraw } from '../../services/wallet'
const amount = ref(''); const selectedCardIndex = ref(0); const showPassword = ref(false); const showError = ref(false); const password = ref(''); const keys = ['1','2','3','4','5','6','7','8','9','','0']
onMounted(() => enforcePortal('agent'))
const selectedCard = computed(() => wallet.cards[selectedCardIndex.value] || wallet.cards[0])
const normalizedAmount = computed(() => Number(amount.value || 0).toFixed(2))
const formattedAvailable = computed(() => `¥${wallet.availableAmount.toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`)
const isAmountValid = computed(() => Number(amount.value) > 0 && Number(amount.value) <= wallet.availableAmount)
function back() { uni.navigateBack() }
function fillAll() { amount.value = wallet.availableAmount.toFixed(2) }
function chooseCard() { uni.showActionSheet({ itemList: wallet.cards.map((item) => `${item.bank}（尾号${item.tail}）`), success: ({ tapIndex }) => { selectedCardIndex.value = tapIndex } }) }
function openPassword() { if (!isAmountValid.value) return; password.value = ''; showPassword.value = true }
function closePassword() { showPassword.value = false; password.value = '' }
function pressKey(key) { if (key === '') return; if (key === 'delete') { password.value = password.value.slice(0, -1); return } if (password.value.length < 6) password.value += key; if (password.value.length === 6) setTimeout(validatePassword, 180) }
function validatePassword() { showPassword.value = false; if (password.value === '123456') { withdraw(Number(amount.value)); uni.showToast({ title: '提现申请已提交', icon: 'success' }); setTimeout(back, 900) } else { showError.value = true } }
function retry() { showError.value = false; password.value = ''; showPassword.value = true }
function goForgot() { showError.value = false; showPassword.value = false; uni.navigateTo({ url: '/pages/agent/payment-password-reset' }) }
</script>

<style lang="scss" scoped>
.withdraw-page{min-height:100vh;background:#f7f8fc;color:#28334c}.nav{display:flex;justify-content:space-between;align-items:center;height:calc(102rpx + env(safe-area-inset-top));padding:env(safe-area-inset-top) 32rpx 0;background:#fff;box-sizing:border-box;font-size:30rpx;font-weight:720}.nav .back{width:60rpx;color:#5966f3;font-size:60rpx;line-height:1}.nav view{width:60rpx}.body{padding:34rpx}.bank-choice{display:flex;align-items:center;gap:18rpx;padding:27rpx;border-radius:22rpx;background:#fff}.bank-logo{display:flex;align-items:center;justify-content:center;width:61rpx;height:61rpx;border-radius:17rpx;background:#e9edff;color:#5966f3;font-size:29rpx;font-weight:750}.bank-choice b,.bank-choice text{display:block}.bank-choice b{font-size:26rpx}.bank-choice text{margin-top:8rpx;color:#8d98aa;font-size:21rpx}.chevron{width:16rpx;height:16rpx;margin-left:auto;border-top:3rpx solid #8d97a9;border-right:3rpx solid #8d97a9;transform:rotate(45deg);box-sizing:border-box}.amount-card{margin-top:23rpx;padding:30rpx;border-radius:23rpx;background:#fff}.amount-card>text{color:#68758c;font-size:23rpx}.amount-input{display:flex;align-items:center;margin-top:34rpx;border-bottom:1rpx solid #e6e9f0}.amount-input>text{padding-right:15rpx;font-size:44rpx;font-weight:700}.amount-input input{height:82rpx;flex:1;font-size:50rpx;font-weight:700}.placeholder{color:#c5cad5;font-size:43rpx}.available{display:flex;justify-content:space-between;margin-top:20rpx;color:#8c97a8;font-size:21rpx}.available text:last-child{color:#5966f3}.confirm{width:100%;margin-top:42rpx;border:0;border-radius:16rpx;background:#5966f3;color:#fff;font-size:28rpx;line-height:88rpx}.confirm[disabled]{background:#c5cad7}.confirm::after{border:0}.rule{display:block;margin-top:22rpx;color:#a0a8b7;text-align:center;font-size:20rpx}.mask,.dialog-mask{position:fixed;inset:0;z-index:20;display:flex;align-items:flex-end;background:rgba(23,31,52,.45)}.password-panel{position:relative;width:100%;padding:38rpx 34rpx calc(30rpx + env(safe-area-inset-bottom));border-radius:30rpx 30rpx 0 0;background:#fff;box-sizing:border-box;text-align:center}.close{position:absolute;top:24rpx;left:30rpx;color:#7f899b;font-size:44rpx}.panel-title,.amount-title,.panel-amount,.forgot{display:block}.panel-title{font-size:31rpx;font-weight:750}.amount-title{margin-top:31rpx;color:#8b95a5;font-size:21rpx}.panel-amount{margin-top:8rpx;font-size:43rpx;font-weight:750}.password-boxes{display:flex;justify-content:center;gap:13rpx;margin-top:31rpx}.box{display:flex;align-items:center;justify-content:center;width:64rpx;height:68rpx;border:1rpx solid #d8dce7;border-radius:12rpx}.box i{width:15rpx;height:15rpx;border-radius:50%;background:#27314a}.forgot{margin:25rpx 0;color:#5966f3;font-size:22rpx}.keypad{display:grid;grid-template-columns:repeat(3,1fr);margin:0 -34rpx -30rpx}.keypad view{height:91rpx;border-top:1rpx solid #e7e9ef;border-right:1rpx solid #e7e9ef;font-size:34rpx;line-height:91rpx}.keypad view:nth-child(3n){border-right:0}.error-dialog{width:560rpx;margin:auto;padding:49rpx 30rpx 28rpx;border-radius:25rpx;background:#fff;text-align:center;font-size:28rpx;font-weight:700}.error-dialog>view{display:flex;gap:17rpx;margin-top:38rpx}.error-dialog button{flex:1;border:1rpx solid #d7dce8;border-radius:14rpx;background:#fff;color:#68758d;font-size:24rpx;line-height:75rpx}.error-dialog .retry{border:0;background:#5966f3;color:#fff}.error-dialog button::after{border:0}</style>
